// The daemon's real responses, generated by its Go tests (go test -run
// Fixtures -update). Annotating each with its wire type is the contract: if a
// response changes shape, regenerating the file makes this stop compiling.
import apply from '../fixtures/apply.json';
import board from '../fixtures/board.json';
import check from '../fixtures/check.json';
import config from '../fixtures/config.json';
import create from '../fixtures/create.json';
import detailBlocked from '../fixtures/detail-blocked.json';
import detailClaimed from '../fixtures/detail-claimed.json';
import detailEpic from '../fixtures/detail-epic.json';
import detailOdd from '../fixtures/detail-odd.json';
import errorBlocked from '../fixtures/error-blocked.json';
import errorClaimedByOther from '../fixtures/error-claimed-by-other.json';
import errorClaimedByYou from '../fixtures/error-claimed-by-you.json';
import errorInvalid from '../fixtures/error-invalid.json';
import primer from '../fixtures/primer.json';
import search from '../fixtures/search.json';
import triage from '../fixtures/triage.json';
import type {
  ApplyResult,
  Board,
  CheckResult,
  Config,
  CreateResult,
  Detail,
  Primer,
  Problem,
  SearchResult,
  TriageResult,
} from '../types';

export const fx = {
  config: config satisfies Config,
  board: board satisfies Board,
  primer: primer satisfies Primer,
  search: search satisfies SearchResult,
  triage: triage satisfies TriageResult,
  claimed: detailClaimed satisfies Detail,
  blocked: detailBlocked satisfies Detail,
  epic: detailEpic satisfies Detail,
  odd: detailOdd satisfies Detail,
  create: create satisfies CreateResult,
  check: check satisfies CheckResult,
  apply: apply satisfies ApplyResult,
  claimedByOther: errorClaimedByOther satisfies Problem,
  claimedByYou: errorClaimedByYou satisfies Problem,
  blockedError: errorBlocked satisfies Problem,
  invalid: errorInvalid satisfies Problem,
};
